// Mappa rapida key → info
export const LOCATION_BY_KEY = {};
CAMPANIA_LOCATIONS.forEach(loc => { LOCATION_BY_KEY[loc.key] = loc; });

export const LOCATIONS_SORTED = [...CAMPANIA_LOCATIONS].sort((a, b) => a.label.localeCompare(b.label, 'it'));

export const LOCATIONS_BY_AREA = {};
CAMPANIA_LOCATIONS.forEach(loc => {
  if (!LOCATIONS_BY_AREA[loc.area]) LOCATIONS_BY_AREA[loc.area] = [];
  LOCATIONS_BY_AREA[loc.area].push(loc);
});

export const LABEL_TO_KEY = {};
CAMPANIA_LOCATIONS.forEach(loc => {
  const normalized = loc.label.toLowerCase()
    .replace(/[àá]/g, 'a').replace(/[èé]/g, 'e').replace(/[ìí]/g, 'i')
    .replace(/[òó]/g, 'o').replace(/[ùú]/g, 'u')
    .replace(/['']/g, '').replace(/[\/\-]/g, ' ').replace(/\s+/g, ' ').trim();
  LABEL_TO_KEY[normalized] = loc.key;
  LABEL_TO_KEY[loc.label] = loc.key;
});